window.WBSC_QDICT = window.WBSC_QDICT || {};
WBSC_QDICT["es"] = {"m01-mkc":{"questions":[{"options":["Motivated (motivado) - mantener el entusiasmo en cada partido","Methodical (metódico) - seguir la misma rutina en cada partido","Managed (dirigido) - aceptar la corrección de los entrenadores sin cuestionarla","Mobile (móvil) - mantener el dinamismo y estar en posición"],"q":"En el acrónimo del árbitro de la Guía de Aprendizaje de Fundamentos («So, you want to be an umpire…»), ¿qué significa la letra M?"},{"options":["Estadístico - llevar el recuento de lanzamientos de ambos equipos","Entrenador - aconsejar a los jugadores cómo jugar su posición","Comunicador - hablar y escuchar de forma eficaz con los compañeros, los jugadores y los entrenadores","Enlace con patrocinadores - gestionar los acuerdos de patrocinio"],"q":"El Módulo 1 describe varias funciones que desempeña un árbitro competente. ¿Cuál de las siguientes es una de ellas?"},{"options":["60 minutos","45 minutos","30 minutos","90 minutos"],"q":"Según el Código Ético del Árbitro de la WBSC, ¿con cuánta antelación respecto a la hora programada del partido debe un árbitro cumplir su designación y presentarse en la sede?"},{"options":["Dar el beneficio de la duda al equipo local","Decidir sin tener en cuenta el marcador","Consultar a ambos entrenadores principales antes de las jugadas dudosas","Favorecer al equipo al que le quedan menos desafíos"],"q":"El Código Ético establece que los árbitros deben ser justos e imparciales en sus decisiones. ¿Qué dice concretamente que significa esto?"},{"options":["El marcador","El dugout","El círculo de espera","La base o la zona de la jugada"],"q":"La Teoría de los Cuatro Elementos Esenciales (FEET) del Módulo 3 enumera cuatro cosas que todo árbitro debe mantener a la vista. ¿Cuál de las siguientes es una de ellas?"}],"title":"Guía de Aprendizaje de Fundamentos","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m01-pca":{"questions":[{"options":["Se declara ilegal al lanzador porque el equipo ha superado las tres conferencias defensivas permitidas por partido.","No ocurre nada: las conferencias defensivas son ilimitadas siempre que no sean para comprobar una lesión.","El entrenador principal es expulsado automáticamente por superar el límite de conferencias.","La conferencia simplemente no se contabiliza por ser la cuarta del partido."],"q":"Durante la entrada del Equipo A, el entrenador principal va al montículo para una cuarta conferencia defensiva en un único partido de 7 entradas para hablar de la estrategia de lanzamiento. Según la guía, ¿cuál es el resultado correcto?"},{"options":["Evitar mencionar la jugada para no avergonzar al árbitro que la falló.","Informar de la jugada fallada directamente al UIC sin hablarlo antes con el equipo arbitral.","Confrontar de inmediato al árbitro por el error en el campo antes de irse.","Hablar de la jugada con honestidad y respeto en la reunión posterior, centrarse en aprender en lugar de culpar y pedir permiso antes de cuestionar la decisión de otro árbitro."],"q":"Después del partido, un árbitro de base que falló una jugada ajustada en segunda quiere revisarla con el equipo arbitral. Según el enfoque de la guía para las reuniones posteriores, ¿cuál es la forma correcta de abordarlo?"},{"options":["Continuar el juego, ya que solo ver un relámpago, y no solo oír truenos, exige suspenderlo.","Pedir de inmediato «Time», suspender el juego y ordenar que todos los jugadores abandonen el campo.","Esperar y vigilar unos minutos más antes de decidir.","Continuar el juego, pero alejar del campo todo el equipamiento metálico."],"q":"Durante un partido se oyen truenos, pero no se ha visto ningún relámpago. Según el protocolo de seguridad ante tormentas de la guía, ¿qué debe hacer el árbitro?"},{"options":["Se concede la primera base al bateador, ya que cualquier bateador golpeado por un lanzamiento va a primera.","El árbitro debe preguntar al bateador si intentó esquivar el lanzamiento antes de dictaminar nada.","No se concede la primera base al bateador, porque no se puede conceder una base a un bateador golpeado por un lanzamiento que estaba en la zona de strike.","Se dictamina balk en el lanzamiento y todos los corredores avanzan una base."],"q":"Un bateador está muy dentro del cajón de bateo, encimado al plato, y es golpeado por un lanzamiento que estaba realmente dentro de la zona de strike. Según la guía, ¿cuál es el fallo correcto?"},{"options":["No hay problema: justo encima de la base se obtiene la visión más clara de una jugada forzada.","El árbitro debió usar la Teoría Dentro-Fuera, ya que esa solo se aplica a los fly.","El árbitro debió salir hacia el outfield en lugar de quedarse en el infield.","Desde justo encima de la base, la pelota, el fildeador, el corredor y el borde de entrada pueden parecer alineados, lo que dificulta juzgar el momento; el árbitro debe trabajar justo antes del borde de entrada y con un ligero ángulo."],"q":"En una jugada forzada en segunda base, el árbitro de base queda de pie justo encima de la base cuando llegan el tiro y el corredor. Según los principios de posicionamiento de la guía, ¿cuál es el problema y desde dónde debió trabajar el árbitro?"},{"options":["Quedarse fuera del diamante, más allá de las líneas de base.","Moverse directamente hacia el plato, sin importar dónde esté la pelota.","Moverse dentro del diamante, entre las líneas de base.","Permanecer en la zona de espera hasta que se fildee la pelota."],"q":"Se batea con fuerza una pelota hacia el hueco del outfield. Según la Teoría Dentro-Fuera, ¿hacia dónde debe moverse el árbitro de base para mantener los Cuatro Elementos Esenciales frente a él?"},{"options":["Volver hacia el infield para ayudar a cubrir la jugada en segunda base.","Quedarse fuera y dejar que terminen todas las jugadas, ya que regresar podría provocar que dos árbitros dictaminen la misma jugada.","Regresar de inmediato a su posición inicial sin importar las demás jugadas.","Pedir tiempo para reordenar las posiciones de los árbitros."],"q":"Un árbitro de base ha salido al outfield para dictaminar sobre un fly. Cuando el tiro regresa y se desarrolla una jugada en segunda base, que ya cubre otro árbitro, ¿qué debe hacer el árbitro que salió?"},{"options":["Expulsar al entrenador siguiendo el procedimiento de expulsión: esperar a que se detenga el juego, ser decidido y usar la señal de expulsión.","Ignorar los comentarios y continuar el partido para evitar que se agrave.","Dar una segunda advertencia antes de tomar cualquier otra medida.","Declarar de inmediato el partido perdido por incomparecencia."],"q":"Un entrenador principal ya ha recibido una advertencia por protestar una decisión de swing a medias, pero sigue protestando bolas y strikes y dirige un insulto personal al árbitro. Según la guía, ¿cuál es la respuesta adecuada?"},{"options":["Sí: la aplicación errónea de una regla es siempre un motivo válido de protesta, sin importar el momento.","No: aunque aplicar mal una regla es un motivo válido de protesta, no se dio aviso antes del siguiente lanzamiento como se exige.","Sí, pero solo si el entrenador la presenta por escrito en un plazo de 48 horas.","No: las disputas sobre las reglas de sustitución nunca pueden protestarse en ninguna circunstancia."],"q":"Un entrenador quiere presentar una protesta porque los árbitros aplicaron mal una regla de sustitución en la media entrada anterior, pero no lo plantea hasta que ya se ha lanzado una pelota en la media entrada siguiente. Según la guía, ¿es válida esta protesta?"},{"options":["Decir con claridad «Strike three... Out!», porque el bateador queda automáticamente fuera por regla en esta situación, y reforzar la decisión si el bateador echa a correr hacia primera.","Señalar de inmediato safe, ya que la pelota no fue atrapada.","No decir nada, ya que se espera que el bateador sepa que la pelota no fue atrapada.","Esperar a que el equipo a la defensiva apele antes de dictaminar nada."],"q":"Con un corredor en primera y un out, el bateador hace swing y falla un tercer strike que el receptor no atrapa limpiamente. Según la guía, ¿qué debe hacer el árbitro de home?"}],"title":"Guía de Aprendizaje de Fundamentos","nextLabel":"Continúa con el Módulo 02 - Mecánica de campo de un árbitro"},"m02-mkc":{"questions":[{"options":["La pelota, los jugadores a la defensiva, los jugadores a la ofensiva y la base o la zona de la jugada","La pelota, los corredores, los entrenadores y el marcador","El lanzador, el receptor, el bateador y el infield","La pelota, los fildeadores, las líneas de foul y los dugouts"],"q":"Según la descripción general del Sistema de Un Árbitro, ¿cuáles son los «Cuatro Elementos Esenciales» que el árbitro debe intentar mantener siempre a la vista?"},{"options":["Permanecer detrás del plato hasta que se fildee la pelota","Salir rápidamente de detrás del plato hacia el infield para tener la mejor visión de la jugada","Pedir «Time» de inmediato para reordenar la defensa","Moverse directamente a primera base sin importar adónde se batee la pelota"],"q":"En el Sistema de Un Árbitro, ¿qué debe hacer el árbitro en cada bola bateada, antes de dictaminar nada?"},{"options":["«Umpire-in-Chief» o «UIC»","«Home» o «HU»","«Base Umpire» o «BU»","«Plate» o «PU»"],"q":"Según la sección de Convenciones, ¿cómo se denomina al árbitro de home en todo este manual?"},{"options":["Tres","Siete","Cinco","Diez"],"q":"Según la orientación sobre la posición inicial del árbitro de home, ¿cuántos lanzamientos de calentamiento se permiten a cada lanzador en la primera entrada y con cada lanzador nuevo?"},{"options":["Por el lado derecho, salvo que el bateador sea zurdo","Por el lado más cercano a donde se bateó la pelota","Directamente por el centro, entre el receptor y el bateador","Por el lado izquierdo, incluso con un bateador zurdo"],"q":"En cada bola bateada, ¿por qué lado indica el manual que debe salir el árbitro de home de detrás del receptor?"}],"title":"Fundamentos - Mecánica de campo de un árbitro","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m02-pca":{"questions":[{"options":["Hacia el territorio de foul, en dirección a tercera base","Con decisión, hacia delante del plato en dirección a la zona del lanzador","Directamente por la línea de primera base, siguiendo al bateador-corredor","Quedarse detrás del receptor y dictaminar desde el plato"],"q":"No hay corredores en base y el bateador batea un rodado rutinario al shortstop. Según la mecánica de «Sin corredores en base», ¿hacia dónde debe moverse el árbitro de home para tener la mejor visión de la jugada?"},{"options":["Moverse hacia el territorio de foul, en dirección a tercera base","Moverse hacia delante del plato en dirección a la zona del lanzador, como cuando no hay corredores en base","Permanecer inmóvil detrás del receptor","Correr directamente a primera base"],"q":"Hay un corredor solo en tercera base y el bateador batea un rodado hacia el tercera base. Según la mecánica de «Corredor en tercera base», ¿qué movimiento debe hacer el árbitro de home?"},{"options":["Hacia delante del plato, en dirección a la zona del lanzador","Hacia la línea de foul del jardín derecho","Directamente detrás de segunda base","Hacia el territorio de foul, en dirección a tercera base"],"q":"Con las bases llenas, el bateador batea un fly hacia el jardín derecho corto. De acuerdo con la mecánica de «Bases llenas» (que sigue el mismo patrón que Corredor en tercera base), ¿hacia dónde debe moverse el árbitro?"},{"options":["Dictaminar de inmediato al ver el tiro y luego confirmar con una señal","Señalar primero y después cantar verbalmente","Parar… Esperar… Dictaminar y señalar","Moverse continuamente mientras se dictamina para mantener el ángulo sobre la jugada"],"q":"El árbitro de home se ha movido a la posición para una posible jugada en primera base sobre un rodado. ¿Qué secuencia prescribe el manual para dictaminar?"},{"options":["Solo si la pelota es fair o foul","La distancia de despegue del corredor","Si el fildeador es zurdo o diestro","Si hay atrapada o no"],"q":"Se batea un fly hacia el outfield sin corredores en base. Antes de moverse hacia la base donde se hará la jugada, ¿qué debe juzgar el árbitro?"},{"options":["Puede dictaminar y señalar «Time»","Seguir persiguiendo activamente la jugada por si un corredor intenta avanzar de nuevo","Regresar de inmediato a la zona del dugout","Convocar automáticamente una conferencia con los entrenadores"],"q":"La pelota ha regresado al infield tras una jugada en el outfield y el juego se ha detenido por completo. Según el manual, ¿qué debe hacer el árbitro de home?"},{"options":["El bateador-corredor que va hacia primera base","El corredor de primera base","El corredor de segunda base (el corredor adelantado)","El corredor que esté físicamente más cerca de la posición actual del árbitro"],"q":"Con corredores en primera y segunda base, se batea un fly hacia el jardín izquierdo que puede ser atrapado o no. De acuerdo con la instrucción del Sistema de Un Árbitro de dar prioridad en el posicionamiento, ¿qué corredor debe influir más en la posición del árbitro?"},{"options":["Permanecer fijo en la jugada de primera base hasta que termine por completo","Desplazarse hacia donde puede producirse la siguiente jugada, sobre todo porque es una posible jugada de tag","Pedir «Time» de inmediato en cuanto se suelta el tiro a primera","Moverse al outfield para preparar al siguiente bateador"],"q":"Se batea un rodado con un corredor en primera base. El tiro a primera para el bateador-corredor parece una jugada rutinaria y sin oposición, pero el corredor de primera puede intentar avanzar con el tiro. ¿Qué indica el manual que debe hacer el árbitro?"},{"options":["Mantenerse cerca de la línea para dictaminar fair/foul","Señalar «Out» de inmediato antes de que termine la jugada","Declarar out al corredor por correr fuera de la línea de base","Pedir ayuda al coach de tercera base"],"q":"Se batea con fuerza un rodado por la línea de tercera base con un corredor en tercera. Además de moverse hacia el territorio de foul en dirección a tercera base, ¿qué responsabilidad adicional asigna el manual al árbitro en esta situación?"},{"options":["Colocarse siempre exactamente a mitad de camino entre las dos bases implicadas en la jugada","Asegurarse de que la posición elegida no lo ponga en el camino de un jugador ni de una pelota lanzada","Mirar siempre al lanzador, sin importar dónde se desarrolle la jugada","Mantener siempre una distancia fija respecto a la base"],"q":"Mientras se mueve con decisión para ponerse en posición para una jugada que se está desarrollando, ¿qué principio de posicionamiento debe observar el árbitro, según la descripción general del Sistema de Un Árbitro?"}],"title":"Fundamentos - Mecánica de campo de un árbitro","nextLabel":"Continúa con el Módulo 03 - Mecánica de campo de dos árbitros"},"m03-mkc":{"questions":[{"options":["La pelota","El marcador","Los jugadores a la ofensiva","Los jugadores a la defensiva"],"q":"Según el manual del Sistema de Dos Árbitros, ¿cuál de los siguientes NO es uno de los «Cuatro Elementos Esenciales» que un árbitro debe mantener sin obstrucciones a la vista?"},{"options":["Ambos árbitros conjuntamente","El árbitro de base","El árbitro que llegue primero","El árbitro de home"],"q":"Según el Principio de División del Sistema de Dos Árbitros, ¿qué árbitro es responsable de las decisiones en home y en tercera base en circunstancias normales?"},{"options":["Hacia el infield","Más adentro del outfield, hacia la pelota","A una posición sobre la línea de foul","Detrás del plato"],"q":"Según el Principio Infield/Outfield, ¿hacia dónde se mueve el árbitro de base cuando la pelota se batea al outfield?"},{"options":["El corredor adelantado es siempre el más rápido en base y necesita una supervisión más cercana","El árbitro de base siempre debe colocarse más cerca de segunda base, sin importar los corredores","El árbitro de base se coloca con el corredor adelantado porque se espera que el receptor intente una jugada de pickoff sobre ese corredor","El árbitro de home delega la cobertura del corredor adelantado para evitar la fatiga"],"q":"¿Cuál es la razón de ser del Principio del Corredor Adelantado en el Sistema de Dos Árbitros?"},{"options":["4-5 metros (15 pies) detrás de la línea de base, en territorio fair","Directamente detrás de la placa del lanzador, de cara al plato","3,5 metros (10-12 pies) detrás de primera base, sobre la línea de foul","5,5 metros (18 pies) detrás de primera base en territorio de foul, a 150 mm (6 pulgadas) de la línea"],"q":"Sin corredores en base, ¿cuál es la posición inicial del árbitro de base según el manual?"}],"title":"Fundamentos - Mecánica de campo de dos árbitros","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m03-pca":{"questions":[{"options":["El árbitro de home, porque es una jugada forzada","El árbitro que esté físicamente más cerca de la base","El árbitro de base, que dictamina todas las jugadas del primer tiro en las jugadas de base","El árbitro de home, porque la bola bateada cayó en territorio fair"],"q":"Sin corredores en base, el bateador batea un rodado rutinario al shortstop, que tira a primera base. ¿Qué árbitro es responsable de la decisión en primera base?"},{"options":["Anticipar el doble play, moverse rápidamente hacia la base donde se hará la primera jugada y dictaminar todas las jugadas del primer tiro","Permanecer en la posición de espera en primera base hasta que termine el tiro","Moverse de inmediato a tercera base para cubrir el avance de R1","Ceder la cobertura de primera base al árbitro de home"],"q":"Con un corredor en primera base, el bateador batea un rodado que se convierte en un posible doble play. Según el manual, ¿qué debe hacer el árbitro de base?"},{"options":["El árbitro de home","El árbitro de base","Ambos árbitros conjuntamente","Ninguno: en los fly atrapados no se juzgan los tag-ups"],"q":"Con un corredor en primera base, el bateador batea un fly al outfield que es atrapado. ¿Qué árbitro es responsable de la decisión del tag-up en primera base?"},{"options":["El árbitro de home, según la regla general del Principio de División para tercera base","El árbitro situado más cerca del plato","El árbitro que tenga el ángulo más claro en ese momento","El árbitro de base"],"q":"Con corredores en primera y segunda base, R2 intenta robar tercera base en el lanzamiento. Según las excepciones al Principio de División, ¿qué árbitro tiene la decisión en tercera base?"},{"options":["R2, el corredor que estaba originalmente en segunda base","El bateador-corredor","R3, el corredor que estaba originalmente en tercera base","Ninguno: el árbitro de home lleva a todos los corredores hasta tercera base en los batazos al outfield"],"q":"Con corredores en segunda y tercera base, el bateador batea un fly profundo al outfield. Según el manual, ¿qué corredor lleva el árbitro de base hasta tercera base en esta jugada?"},{"options":["Como una jugada de tag que obliga al árbitro a moverse a 3,5 metros","Solo como un juicio de fair/foul","Como algo que requiere una apelación defensiva","Como una jugada forzada"],"q":"Con las bases llenas, el bateador batea un rodado a un jugador de cuadro. Según la nota del manual para esta situación, ¿cómo debe tratarse una jugada en cualquier base?"},{"options":["El árbitro de home, ya que las decisiones en tercera base siempre corresponden al árbitro de home según el Principio de División","El árbitro de base","El árbitro que haya iniciado la jugada más cerca de tercera base","El árbitro de home, porque el árbitro de base solo cubre las decisiones de primera y segunda base"],"q":"El bateador batea una pelota al outfield y, como bateador-corredor, avanza hasta tercera base. Según las excepciones al Principio de División, ¿quién dictamina sobre el bateador-corredor en tercera base?"},{"options":["5,5 metros (18 pies) detrás de primera base, en territorio de foul","Detrás y al lado del jugador de segunda base, inclinado hacia primera base","Detrás y al lado del shortstop, inclinado hacia el corredor de segunda base, con vista del lanzador, del corredor y de la zona del plato","En el césped del outfield, detrás de segunda base"],"q":"Con un corredor solo en segunda base y antes del lanzamiento, ¿dónde debe colocarse el árbitro de base?"},{"options":["Acercarse a unos 3,5 metros (10-12 pies) para ver y dictaminar la jugada","Permanecer a 5,5 metros (18 pies), ya que esa distancia se aplica a todas las decisiones","Moverse a 4-5 metros (15 pies) detrás de la línea de base","Retroceder más hacia el territorio de foul para obtener un ángulo más amplio"],"q":"El árbitro de base está colocado para una posible jugada en primera base y queda claro que el tiro requerirá un tag en lugar de un force. Según el manual, ¿qué ajuste debe hacer el árbitro de base?"},{"options":["El árbitro de base, ya que dictamina todas las jugadas, incluidos los tiros siguientes","Ambos árbitros deben dictaminarla simultáneamente","El árbitro que esté colocado en territorio fair","El árbitro de home, que es responsable de las jugadas sucesivas en tercera base o en home tras la primera jugada del infield"],"q":"Con corredores en primera y tercera base, se batea un rodado al infield. La defensa hace la primera jugada (un force en segunda base) y luego tira a home intentando sacar al corredor de tercera. ¿Qué árbitro es responsable de dictaminar esta segunda jugada posterior en home?"}],"title":"Fundamentos - Mecánica de campo de dos árbitros","nextLabel":"Continúa con el Módulo 04 - Mecánica de campo de tres árbitros"},"m04-mkc":{"questions":[{"options":["La pelota, los jugadores a la defensiva, los jugadores a la ofensiva y la base o la zona de la jugada","La pelota, el lanzador, el receptor y la base","La pelota, el corredor, el entrenador y el marcador","La pelota, el fildeador, el dugout y la línea de foul"],"q":"Según los «Cuatro Elementos Esenciales» del manual del Sistema de Tres Árbitros, ¿cuáles son las cuatro cosas que un árbitro debe mantener sin obstrucciones a la vista para tener la jugada frente a él?"},{"options":["El árbitro de base que permanece","El árbitro de home","El árbitro que esté más cerca de tercera base","Ambos árbitros conjuntamente"],"q":"Según el Principio de División de los «Dos Principios Básicos de Cobertura» del Sistema de Tres Árbitros, cuando un árbitro de base sale a un fly, ¿qué árbitro dictamina todas las jugadas en home y en tercera base?"},{"options":["Correr hasta la malla de fondo para comprobar si hay interferencia","Indicar al receptor que se levante antes de cada lanzamiento","Dar un pequeño paso a la izquierda del árbitro de home para salir de detrás del receptor","Colocarse directamente detrás del receptor para obtener el mejor ángulo"],"q":"¿Qué significa «despejar al receptor» (clearing the catcher) para el árbitro de home, según el manual del Sistema de Tres Árbitros?"},{"options":["En cuanto el lanzador adopta la posición de set","Durante la reunión previa al partido","Solo después de que la pelota esté en juego","Cuando el lanzador inicia el lanzamiento"],"q":"En la Posición de Espera del Árbitro de Base descrita en este manual, ¿cuándo debe adoptar el árbitro la posición de «listo», flexionando ligeramente las rodillas y apoyando el peso en la parte delantera de los pies?"},{"options":["Moverse más allá de la línea de base para respaldar la jugada","Permanecer en la posición de espera en su base original","Rotar hacia el interior del diamante","Seguir la pelota hacia la cerca del outfield"],"q":"Según el Principio Infield/Outfield del Sistema de Tres Árbitros, ¿qué debe hacer un árbitro de base que NO sale a un fly una vez que la pelota está en el outfield?"}],"title":"Fundamentos - Mecánica de campo de tres árbitros","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m04-pca":{"questions":[{"options":["El árbitro de home, siguiendo al corredor hacia segunda base","U1, que se queda en primera base y cubre también segunda","U3, que rota a segunda base alineado con el árbitro de home","U3 permanece en tercera base y no rota"],"q":"Sin corredores en base, se batea un rodado al infield que produce una posible jugada forzada en primera base. Si el bateador-corredor es declarado safe en primera y continúa hacia segunda base, ¿qué árbitro ha rotado a la posición para dictaminar esa jugada, según el manual del Sistema de Tres Árbitros?"},{"options":["El árbitro de home","U3","U1 regresa del outfield para llevar al corredor","La cobertura se reparte por igual entre el árbitro de home y U3"],"q":"Sin corredores en base, U1 sale a un fly al outfield. Si la pelota no es atrapada, ¿qué árbitro es responsable de llevar al bateador-corredor hasta segunda base y rodear hasta tercera?"},{"options":["Da un paso hacia segunda base para obtener un ángulo sobre el tiro","Se mueve a tercera base para cubrir un posible avance","Permanece en la posición de espera original, fuera de la línea de tercera base","Sale hacia el outfield para respaldar el tiro"],"q":"Con un corredor en primera base, se batea un rodado al infield que presenta un posible doble play. ¿Qué hace U3 en previsión del tiro a segunda base?"},{"options":["U3","El árbitro de home","U1 y U3 se reparten las decisiones","U1"],"q":"Con un corredor solo en segunda base, se batea un rodado al infield. ¿Qué árbitro es responsable de las decisiones tanto en primera como en segunda base en esta situación?"},{"options":["U1","U3, después de liberar tercera base","El árbitro de home, subiendo por la línea de primera base","Ningún árbitro: la jugada es de pelota muerta"],"q":"Con un corredor solo en tercera base, se batea un rodado al infield. Si U3 no puede liberar a R1 en tercera base (R1 no avanza a home), ¿qué árbitro puede tener que llevar al bateador-corredor a segunda base y dictaminar la jugada?"},{"options":["U3","El árbitro de home","U1, antes de salir hacia el outfield","Ningún árbitro vigila el tag-up en esta situación"],"q":"Con un corredor en tercera base, U1 sale a un fly. ¿Qué árbitro se mueve a la zona de espera entre home y tercera base para vigilar el tag-up de R1, preparándose a la vez para una posible decisión en home?"},{"options":["Se queda en territorio de foul detrás de tercera base","Rota de inmediato hasta tercera base","Se mueve hacia territorio fair aproximadamente un paso, en previsión de una jugada sobre R1","Sale al outfield para respaldar un posible tiro desviado"],"q":"Con corredores en primera y segunda base, se batea un rodado al infield que presenta un posible doble play. ¿Qué hace U3 en previsión de que el corredor adelantado (R1) avance desde segunda base?"},{"options":["Permanece en tercera base sin importar el avance de R1","Sigue a R1 hacia home","Rota de inmediato a primera base","Se mueve hacia territorio fair aproximadamente un paso, en previsión de una jugada sobre R2 que avanza desde segunda base"],"q":"Con corredores en segunda y tercera base, se batea un rodado al infield. Si R1 (el corredor de tercera) avanza hacia home, ¿qué hace U3, según el manual?"},{"options":["Primera base","Tercera base","El árbitro de home permanece en home","Segunda base, junto a U3"],"q":"Con un corredor en primera base, la pelota atraviesa el infield hacia el outfield y ningún árbitro sale. Mientras R1 avanza hacia segunda base, ¿hacia dónde rota el árbitro de home en preparación de una posible decisión?"},{"options":["Liberarse para cubrir home","Volver a salir más allá de la línea de base, en territorio fair","Permanecer en la línea de foul a la altura de la base","Rotar hacia el interior del diamante"],"q":"Con un corredor en segunda base, la pelota se batea a través del infield hacia el jardín derecho. Según la nota del manual, si existe la posibilidad de una jugada en tercera base con el tiro de regreso, ¿qué debe hacer U3?"}],"title":"Fundamentos - Mecánica de campo de tres árbitros","nextLabel":"Continúa con el Módulo 05 - Apéndice 4: Filosofías de posicionamiento de élite"},"m05-mkc":{"questions":[{"options":["La posición del árbitro, la velocidad del corredor, el ruido del público y el marcador","El lanzador, el receptor, el bateador y el plato","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La posición inicial, la posición de decisión, el punto focal y el borde de entrada"],"q":"Según los Conceptos Clave y el Glosario del Apéndice 4, ¿cuáles son los «Cuatro Elementos Esenciales» que un árbitro debe observar juntos para tomar una decisión precisa?"},{"options":["Una distorsión visual que se produce cuando el árbitro ve una jugada desde un mal ángulo que impide separar con claridad los elementos de la jugada y su momento","Una infracción que se produce cuando el pie de apoyo del lanzador cae fuera del carril de lanzamiento","El retraso entre que un árbitro ve una jugada y señala una decisión","Un error de mecánica causado por empezar demasiado lejos de la base"],"q":"En los Conceptos Clave y el Glosario del Apéndice 4, ¿cómo se define el «Error de Paralaje»?"},{"options":["Directamente sobre la línea de foul, a la altura de primera base","A unos 3-4 metros (10-12 pies) directamente detrás de home, alineado con el eje central del plato","Dentro del diamante, a mitad de camino entre home y la placa del lanzador","En el Ángulo Diagonal de Segunda Base, a 3-4 metros detrás de segunda base"],"q":"¿Dónde se encuentra por lo general la Posición del Punto del Plato (POP)?"},{"options":["Ver - Moverse - Reaccionar - Dictaminar","Posicionarse - Seguir - Juzgar - Señalar","Observar - Esperar - Confirmar - Anunciar","Parar - Ver - Decidir - Señalar"],"q":"¿Qué secuencia disciplinada identifica el Apéndice 4 como la técnica que usan los árbitros para evitar la anticipación y el sesgo cognitivo antes de tomar y comunicar una decisión?"},{"options":["El Apéndice 4 sustituye al Apéndice 5 para los árbitros por debajo del nivel de élite","El Apéndice 4 y el Apéndice 5 cubren el mismo contenido en formatos distintos","El Apéndice 4 aporta el porqué; el Apéndice 5 aportará el cómo","El Apéndice 4 es solo para entrenadores, mientras que el Apéndice 5 es solo para árbitros"],"q":"¿Cómo describe el Apéndice 4 su relación con el Apéndice 5?"}],"title":"Apéndice 4: Filosofías de posicionamiento de élite","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m05-pca":{"questions":[{"options":["La señalización anticipada, porque el árbitro preparó la señal antes de que empezara la jugada","El sesgo de confirmación, porque fijarse en la acción del tag puede hacer que el cerebro confirme prematuramente un out y anule la relación real entre la pelota, el corredor y la base","El error de paralaje, porque el árbitro estaba colocado demasiado lejos de la jugada","Un incumplimiento de las responsabilidades primarias, porque el árbitro no rotó a la base correcta"],"q":"Durante una jugada de tag muy ajustada en tercera base, el árbitro ve claramente que el guante del fildeador toca la pierna del corredor, pero no sigue con claridad si la mano del corredor ya había llegado a la base. El árbitro declara out al corredor solo por el contacto del guante. ¿Qué principio del Apéndice 4 explica mejor el riesgo de este proceso de decisión?"},{"options":["No preocupa, porque la posición de slot del árbitro de home está alineada con todas las partes del campo","El árbitro de home debería dictaminar la jugada recordando la ubicación del lanzamiento y no la bola bateada","Solo preocupa para los juicios de jonrón, no para las líneas duras cerca de una base","El paralaje puede hacer que la pelota parezca fair o foul de forma errónea desde detrás del plato; la mecánica exige que el árbitro esté en la línea de foul para juzgar la jugada con precisión"],"q":"Una línea dura pasa cerca de la base de tercera. El árbitro de home, colocado detrás del receptor, es el único árbitro con vista de la jugada. Según la explicación del error de paralaje del Apéndice 4, ¿por qué preocupa esta posición y qué exige la mecánica correcta?"},{"options":["Permanecer fijo en el Ángulo Diagonal de Segunda Base sin importar cómo se desarrolle la jugada, ya que es la referencia inicial designada","Moverse de inmediato a la posición del Punto del Plato para obtener un mejor ángulo","Ajustar su posición a lo largo de la diagonal o salirse de ella según sea necesario, ya que la prioridad es siempre mantener una vista sin obstrucciones de los elementos clave","Pedir tiempo y reposicionarse solo después de que termine la jugada"],"q":"Un corredor que intenta evitar un tag de barrido en segunda base se desliza hacia la esquina trasera de la base, lejos de la posición del árbitro en el Ángulo Diagonal de Segunda Base. ¿Qué indica el Apéndice 4 que debe hacer el árbitro en esta situación?"},{"options":["El árbitro estaba en la posición equivocada o no esperó a que la jugada se desarrollara correctamente","El corredor cometió interferencia y debe ser declarado out automáticamente","El árbitro anticipó correctamente la jugada y debería mantenerse firme la próxima vez","Es una parte normal e inevitable de la mecánica de élite que no requiere ningún ajuste"],"q":"En una posible jugada de tag, un corredor corre directamente hacia el árbitro, obligándolo a moverse de repente para evitar una colisión. ¿Qué dice el Apéndice 4 que indica esta situación?"},{"options":["No decir nada, porque solo el árbitro de home tiene autoridad para dictaminar un lanzamiento ilegal","Esperar a la siguiente entrada para plantear el asunto al árbitro de home en privado","Si está seguro, dictaminar el lanzamiento ilegal, ya que la mecánica de la WBSC permite al árbitro cercano a segunda base controlar el pie de apoyo cuando está completamente fuera del carril de lanzamiento","Avisar discretamente al árbitro de home, pero nunca dictaminar la infracción directamente"],"q":"Durante un partido, el árbitro situado cerca de segunda base ve con claridad y sin dudas que el pie de apoyo del lanzador cayó completamente fuera del carril de lanzamiento, mientras que el ángulo del árbitro de home no le permite ver con claridad la infracción. Según el Apéndice 4, ¿qué debe hacer el árbitro cercano a segunda base?"},{"options":["Altera el momento de decisión y favorece las decisiones prematuras, porque el cerebro deja de procesar los elementos finales de la acción","No afecta a la precisión, ya que los árbitros con experiencia pueden hacer varias cosas a la vez con eficacia","Mejora el tiempo de reacción y es una técnica recomendada para las jugadas muy ajustadas","Solo afecta a las decisiones de bolas y strikes, no a las jugadas de tag"],"q":"Un árbitro empieza a formar mentalmente su señal de «out» mientras el fildeador aún está completando el intento de tag, antes de que la jugada haya terminado del todo. Según el Apéndice 4, ¿cuál es la consecuencia probable de este hábito?"},{"options":["U2 debe salir primero porque U2 tiene la posición inicial más central","Ambos árbitros deben salir a la vez para cubrir doblemente la jugada","Ningún árbitro debe salir; el árbitro de home debe cubrir todos los fly convergentes","U1 debe tener la primera oportunidad de salir, ya que U2 debe dar a U1 o a U3 la primera oportunidad y solo salir si ninguno lo hace"],"q":"En un sistema de cuatro árbitros, se batea un fly al hueco donde se superponen las zonas de cobertura de U1 y U2, y U1 también converge sobre la pelota. Según el Apéndice 4, ¿qué árbitro debe salir primero?"},{"options":["Los pies activos, que se usan únicamente para mantener el equilibrio mientras se está quieto","La técnica de la instantánea mental, en la que el árbitro toma una «fotografía mental» desde el ángulo inicial y otra desde el ángulo mejorado, y las combina en una imagen 3D más clara de la jugada","La corrección de paralaje, que elimina la necesidad de cambiar de posición","El principio del borde de entrada, que exige que el árbitro permanezca en todo momento a 90 grados de la trayectoria del corredor"],"q":"El ángulo inicial de un árbitro en una jugada de tag que se desarrolla es malo, pero el árbitro se mueve con decisión hacia un mejor ángulo cuando llega el tiro. ¿Qué técnica descrita en el Apéndice 4 refleja esto y cuál es su finalidad?"},{"options":["La posición más lejana con el ángulo limpio, porque en todos los casos los ángulos tienen prioridad sobre la distancia","La posición más cercana, porque la proximidad siempre produce el juicio más preciso","Ninguna; el árbitro debe pedir una revisión por video","La posición más cercana, porque la distancia tiene prioridad sobre el ángulo en la cobertura del outfield"],"q":"Un árbitro de base en un sistema de 3 o 4 árbitros debe decidir si sale a un fly. Una posición disponible está más cerca de la jugada, pero ofrece una línea de visión comprometida; otra está más lejos, pero ofrece un ángulo limpio y sin obstrucciones. ¿Qué elección refleja el principio del Apéndice 4 para las decisiones de cobertura del outfield?"},{"options":["Las Responsabilidades Primarias, porque el árbitro siempre debe rotar primero a otra base","El Posicionamiento y los Ajustes Dinámicos, porque no existe una posición «X marca el lugar»: las posiciones inicial y de observación nunca deben darse por la posición final de decisión","La Preparación Previa al Lanzamiento y la Cobertura del Outfield, porque el árbitro no anticipó la profundidad de los jardineros","El Error de Paralaje, porque el árbitro estaba alineado con el plano equivocado"],"q":"Un árbitro en formación trata su posición inicial de manual en segunda base como la posición desde la que debe hacerse cada decisión, incluso cuando un tiro y un tag llevan la jugada hacia el borde de entrada. ¿Qué principio clave del Apéndice 4 no refleja este enfoque?"}],"title":"Apéndice 4: Filosofías de posicionamiento de élite","nextLabel":"Continúa con el Módulo 06 - Apéndice 5: Mecánica de campo de élite"},"m06-mkc":{"questions":[{"options":["El lanzador, el receptor, el bateador y el árbitro de base","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La zona de strike, el despegue del corredor, el tag y el guante del fildeador","La posición inicial, la posición de observación, la posición de decisión y la base"],"q":"En la Teoría de los Cuatro Elementos Esenciales (FEET) del Apéndice 5a, ¿cuáles son los cuatro elementos que los árbitros deben observar juntos para dictaminar correctamente?"},{"options":["1-2 metros (3-6 pies)","6-12 metros (20-40 pies)","3-5 metros (9-15 pies)","2-4 metros (6-12 pies)"],"q":"Según el Apéndice 5a, ¿a qué distancia aproximada detrás de home se encuentra la posición del Punto del Plato (POP)?"},{"options":["A un árbitro que despeja al receptor para obtener una vista sin obstrucciones del campo","A un árbitro que se mueve al borde de entrada de una base para juzgar una jugada de tag","A un árbitro que rota en sentido contrario para cubrir una posición que no ocupa otro árbitro obligado a cubrir una jugada en otro lugar","A un árbitro que vuelve a su posición entre entradas cuando termina una jugada"],"q":"Según el Apéndice 5a, ¿a qué se refiere el «Backfilling»?"},{"options":["Permitir que dos árbitros dedicados al outfield cubran las responsabilidades de los fly, de modo que los demás árbitros puedan permanecer en el infield y cubrir las bases en todo momento","Sustituir al árbitro de home por dos árbitros adicionales de outfield","Eliminar la necesidad de cualquier rotación entre bases","Permitir que todos los árbitros actúen exclusivamente desde territorio de foul"],"q":"¿Qué finalidad asigna el Apéndice 5a a los Sistemas de Cinco y Seis Árbitros?"},{"options":["Apéndice 5a","Apéndice 5d","Apéndice 5c","Apéndice 5b"],"q":"El Apéndice 5 se divide en cuatro subsecciones (5a-5d). ¿Qué subsección abarca la mecánica del Sistema de Tres Árbitros?"}],"title":"Apéndice 5: Mecánica de campo de élite","nextLabel":"Continúa con las presentaciones - Apéndice 5, Parte A: Conceptos clave"},"m06-pca":{"questions":[{"options":["La pelota, el lanzador, el receptor y la base","El corredor, el fildeador, el entrenador y el marcador","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La pelota, el fildeador, el dugout y la línea de foul"],"q":"Según el Apéndice 5a, ¿qué cuatro cosas componen los Cuatro Elementos Esenciales (FEET) que el árbitro debe ver juntos en cada jugada?","why":"Los elementos deben observarse juntos, sobre todo el control de la pelota y los intentos de tag, porque la decisión correcta depende de ver cómo se combinan."},{"options":["Cuando el árbitro está demasiado lejos de la base para oír la jugada","Cuando el árbitro queda alineado en línea recta con el corredor, el fildeador, la pelota y la base o el punto del tag","Cuando el árbitro se mueve con pies activos durante la jugada","Cuando el árbitro está de pie en el borde de entrada de la base"],"q":"Según el Apéndice 5a, ¿cuándo se produce con más frecuencia el error de paralaje?","why":"Alinearse en línea recta reduce la percepción de profundidad y puede distorsionar la secuencia de los hechos. Los árbitros reducen el paralaje ajustando su posición para mantener el ángulo y la separación entre los elementos."},{"options":["Colocarse lo más atrás posible para ver todo el campo","Confiar en que el árbitro de base tome la decisión","Esperar a que la pelota se detenga antes de decidir","Colocarse en el plano de la decisión, por ejemplo sobre la línea de fair/foul"],"q":"Un árbitro quiere eliminar el error de paralaje en una decisión de fair/foul. ¿Qué dice el Apéndice 5a que debe hacer?","why":"Moverse al plano que forma la decisión convierte ese plano en una línea en la vista del árbitro, de modo que se puede juzgar directamente la posición de la pelota respecto a él."},{"options":["5,5 m (18 pies)","3,5 m (12 pies)","4,5 m (15 pies)","7 m (23 pies)"],"q":"Sin corredores en base, ¿a qué distancia aproximada de la base debe empezar un árbitro de base en 1B o 3B, según el Apéndice 5a?","why":"Sin corredores, la posición inicial es de 5,5 m (18 pies) en 1B y 3B, y de 4,5 m (15 pies) en 2B. Se reduce a unos 3,5 m (12 pies) cuando hay un corredor en la base del propio árbitro."},{"options":["Unos 3 m (10 pies) para una jugada forzada y 5 m (16 pies) para una de tag","Unos 5 m (16 pies) para una jugada forzada y 3 m (10 pies) para una de tag","Unos 5 m (16 pies) para ambas","Unos 3 m (10 pies) para ambas"],"q":"En una jugada, ¿qué distancia a la base indica el Apéndice 5a para una jugada forzada y para una jugada de tag?","why":"En una jugada de tag, el árbitro debe estar lo bastante cerca para ajustarse a izquierda o derecha y llegar al borde de entrada manteniendo todos los elementos frente a él."},{"options":["El ángulo","La distancia","El que esté más cerca de la base","Ninguno; el árbitro debe quedarse quieto"],"q":"Cuando el ángulo y la distancia no pueden ser ambos perfectos, ¿cuál tiene prioridad según el Apéndice 5a?","why":"Estar más cerca puede ayudar igualmente al árbitro a hacer movimientos controlados hacia un mejor ángulo, y el error de paralaje aumenta tanto con la distancia como con el ángulo."},{"options":["Es peligroso por los corredores que se deslizan","Le tapa la vista del dugout","Le impide usar la decisión verbal","Los ojos del árbitro quedan alineados verticalmente con la base, de modo que la pelota, el tag y el borde de entrada se reducen a una vista en línea recta sin percepción de profundidad"],"q":"¿Por qué dice el Apéndice 5a que un árbitro nunca debe colocarse directamente sobre una base al hacer una decisión?","why":"A velocidades de élite, la diferencia entre un tag en el borde de entrada y uno más allá puede ser de unos pocos centímetros. Una posición de decisión justo antes del borde de entrada mantiene los elementos visualmente separados."},{"options":["Fuera del diamante","Detrás de home","Dentro del diamante","En la línea de foul"],"q":"Según la Teoría Dentro/Fuera del Apéndice 5a, ¿dónde deben estar los árbitros de base que no han salido cuando la pelota está en el outfield?","why":"Cuando la pelota está en el outfield, los árbitros de base entran; cuando está en el infield, están fuera del diamante. Si algún árbitro sale, todos los demás deben entrar para cubrir las bases y hacer el backfill."},{"options":["Que PU comunique que se queda en HP para la jugada","Que el árbitro de base decida salir a un fly","Que un entrenador pida una conferencia","Que la pelota se devuelva al lanzador"],"q":"Según el Apéndice 5a, ¿qué desencadena una situación de backfill?","why":"Después de que PU comunica que se queda en HP, los árbitros de base se ajustan: el árbitro que no ha salido cubre 3B y U1 rota hacia el interior para cubrir 1B y 2B si es posible."},{"options":["Declarar safe al corredor","Declarar out al corredor, porque todavía está procesando que el tiro fue atrapado","Declarar interferencia","No ver la base"],"q":"En una jugada forzada en la que el corredor llega a la base y después el fildeador recibe el tiro, ¿qué error es más probable que cometa un árbitro que precipita la decisión, según el Apéndice 5a?","why":"Una ligera pausa en una jugada ajustada da al cerebro tiempo para procesar todos los datos en el orden correcto, en lugar de basar la decisión en lo último que se vio."}],"title":"Apéndice 5a: Conceptos clave","nextLabel":"Continúa con la presentación - Apéndice 5b: Sistema de tres árbitros"},"m07-pca":{"questions":[{"options":["A mitad de camino de HP a 1B, fuera de la línea de fair/foul","A dos tercios del camino de HP a 3B","A un tercio del camino de HP a 3B","Detrás de los cajones de bateo, en el punto del plato"],"q":"En el Sistema de Tres Árbitros (Apéndice 5b), ¿dónde se coloca U1 entre entradas?","why":"Entre entradas, PU se coloca a un tercio del camino de HP a 3B, U1 a mitad de camino de HP a 1B y U3 a dos tercios del camino de HP a 3B, todos fuera de las líneas."},{"options":["A unos 3,5 m (12 pies) atrás, a dos tercios del camino de 1B a 2B","A unos 5,5 m (18 pies) detrás de 1B","A unos 3,5 m (12 pies) detrás de 1B, en territorio de foul","En el lado de 3B de 2B"],"q":"En el Sistema de Tres Árbitros, ¿dónde empieza U1 con un corredor solo en 1B?","why":"Sin corredores o con un corredor solo en 3B, la posición inicial es de unos 5,5 m (18 pies) detrás de 1B; con un corredor en 1B es más cercana para que el árbitro pueda mantenerse en territorio de foul con una vista clara."},{"options":["Para no estorbar al bateador en el círculo de espera","Para que el entrenador de tercera base pueda moverse libremente","Para estar listo para rotar a primera base","Para mantener una vista sin obstrucciones del lanzador, el corredor, el bateador y home, y que no le afecte el despegue del corredor cuando se suelta el lanzamiento"],"q":"¿Por qué coloca el Apéndice 5b a U3 a unos 3,5 m (12 pies) detrás de 3B, hasta a 2 m (6 pies) de la línea, cuando hay un corredor en 3B?","why":"La posición inicial se elige para que el árbitro pueda ver todo el lanzamiento y el despegue del corredor sin que el corredor le tape la vista."},{"options":["Hasta donde haga falta, incluso hacia el césped del infield","A unos 3 m (10 pies) de la base en territorio de foul, pero sin pasar de una línea de 45 grados que atraviesa 1B","Directamente al borde de entrada de 1B","Debe permanecer en la posición inicial"],"q":"En un pickoff (tiro de regreso) en 1B, ¿hasta dónde puede moverse U1, según el Apéndice 5b?","why":"Si U1 lee que la jugada será en el borde de entrada, puede entrar hacia territorio fair, manteniendo siempre los Cuatro Elementos Esenciales frente a él."},{"options":["El árbitro de base que permanece en el infield","El árbitro que salió","Nadie; no se vigila al corredor","PU"],"q":"En el Sistema de Tres Árbitros, cuando un árbitro de base sale a un fly, ¿quién asume la responsabilidad del tag-up en 3B?","why":"El árbitro de base que permanece en el infield se encarga de los tag-ups en 1B y 2B, y PU se encarga del tag-up en 3B."},{"options":["U1","U3","PU","El árbitro más cercano al corredor"],"q":"En el Sistema de Tres Árbitros, ¿quién es responsable de la decisión del despegue (lead-off) de un corredor en 2B?","why":"U1 es responsable de las decisiones de despegue de los corredores en 1B y 2B, y U3 de las de un corredor en 3B."},{"options":["U3","U1","PU","U1 y U3 la comparten por igual"],"q":"U1 está en 1B y U3 en 3B sin corredores en base. Se batea un fly al jardinero central (F8, en su posición normal) que se desplaza hacia el jardín derecho. ¿Quién es responsable de la decisión?","why":"U1 toma los fly a F8 que se desplazan hacia RF y foul; U3 toma los fly a F8 que se desplazan hacia LF y foul."},{"options":["U3","U1","PU","ULF"],"q":"U1 está en 1B, U3 está en 2B y hay un corredor en 1B. ¿Quién toma un fly al jardinero izquierdo (F7)?","why":"PU toma los fly a F7 y foul, U1 toma la zona del jardín derecho y foul, y U3 toma F8 y F7 desplazándose hacia CF. Que U1 tome los fly a F9 mantiene a U1 fuera de la trayectoria del corredor y deja a U3 entrar con más facilidad."},{"options":["Quedarse en su base","Entrar en el diamante, cubrir todas las decisiones en 1B o 2B y rotar a 3B por delante del bateador-corredor","Correr a home","Salir también al outfield"],"q":"Cuando U1 o U3 sale a un fly en el Sistema de Tres Árbitros, ¿qué debe hacer el árbitro de base que queda?","why":"Si la pelota es atrapada y el árbitro que queda puede llevar al último corredor a 3B y comunicarse con PU, debe hacerlo, lo que mantiene a PU en home para las jugadas importantes."},{"options":["Quedarse detrás del plato","Correr de inmediato a 3B","Salir hacia el outfield","Seguir al bateador-corredor aproximadamente un tercio del camino hacia 1B (más si hace falta), vigilar la interferencia y dictaminar fair/foul"],"q":"U1 está en 1B y U3 en 3B sin corredores en base y se batea un rodado al infield. Según el Apéndice 5b, ¿cuál es la tarea de PU?","why":"PU sigue al bateador-corredor por un posible tag, por interferencia del bateador-corredor o para ayudar en 1B, y rota a 3B si el bateador-corredor llega a 1B y avanza hacia 2B."}],"title":"Apéndice 5b: Sistema de tres árbitros","nextLabel":"Continúa con la presentación - Apéndice 5c: Sistemas de cuatro, cinco y seis árbitros"},"m08-pca":{"questions":[{"options":["A un tercio del camino de HP a 1B","Detrás de 2B","Junto a PU","A dos tercios del camino de HP a 1B"],"q":"En el Sistema de Cuatro Árbitros (Apéndice 5c), ¿dónde se coloca U2 entre entradas?","why":"Entre entradas, PU se coloca a un tercio del camino de HP a 3B, U1 a un tercio del camino de HP a 1B, U2 a dos tercios del camino de HP a 1B y U3 a dos tercios del camino de HP a 3B."},{"options":["A unos 3,5 m (12 pies)","A unos 4,5 m (15 pies)","A unos 5,5 m (18 pies)","A unos 2 m (6 pies)"],"q":"En el Sistema de Cuatro Árbitros, ¿a qué distancia aproximada detrás de 2B empieza U2 cuando hay un corredor en cualquier base?","why":"Sin corredor, la posición inicial del Ángulo Diagonal de Segunda Base está a unos 4,5 m (15 pies) atrás; con un corredor en cualquier base, a unos 3,5 m (12 pies)."},{"options":["U1","PU","U2","U3"],"q":"En el Sistema de Cuatro Árbitros, ¿quién sale a un fly al jardín central?","why":"U1 sale a los fly al jardín derecho y a F8 que corre hacia la derecha; U3, al jardín izquierdo y a F8 que corre hacia la izquierda. U2 debe dar a U1 o a U3 la primera opción."},{"options":["U2","PU","U3","Nadie"],"q":"En el Sistema de Cuatro Árbitros, U1 sale a un fly. ¿Quién se encarga del tag-up en 1B?","why":"PU se encarga del tag-up en 1B porque PU tiene los Cuatro Elementos Esenciales frente a él en todo momento. U2 se encarga de 2B y U3 de 3B."},{"options":["U1","PU","U3","U2, desde el outfield"],"q":"En el Sistema de Cuatro Árbitros, U2 sale a un fly. ¿Quién se encarga del tag-up en 2B?","why":"U1 conserva 1B, U3 se encarga de 2B, incluido el tag-up, y PU se encarga del tag-up en 3B."},{"options":["U1 siempre hace un button hook hacia el interior","U1 usa el territorio de foul de 1B o sale, y nunca necesita hacer un button hook","U1 se queda en 1B durante toda la jugada","U1 cubre 3B en cada fly"],"q":"¿Qué afirmación sobre U1 en el Sistema de Cuatro Árbitros es correcta, según el Mapa Mnemotécnico de Rotaciones?","why":"U1 también se comunica con PU cuando llega a HP y empuja a PU hacia 3B, y se aparta de HP cuando PU indica una situación de backfill."},{"options":["Quedarse fuera para tener un ángulo agudo sobre el tiro desde el jardín izquierdo para cualquier decisión en 2B","Hacer de inmediato un button hook hacia el interior para cualquier decisión en 2B","Moverse a la zona POP para ayudar a PU","Rotar a 3B"],"q":"Sistema de Cuatro Árbitros. Se batea un rodado al jardín izquierdo y ningún árbitro de base sale. ¿Qué debe hacer U2?","why":"En un batazo a RF o CF, U2 hace un button hook hacia el interior para cualquier decisión en 2B; en un batazo a LF, el ángulo agudo sobre el tiro es mejor desde fuera."},{"options":["Detrás de la cerca del outfield","En la línea de foul a la altura de 2B","Junto a PU, detrás de home","Delante del jardinero, a mitad de camino entre el jardinero y el árbitro de base, hasta un metro fuera de la línea en territorio fair"],"q":"En los Sistemas de Cinco y Seis Árbitros (Apéndice 5d), ¿dónde toman ULF y URF su posición inicial preliminar?","why":"Si LF o RF juega cerca, el árbitro de outfield debe estar siempre delante del jardinero para juzgar con precisión las bolas atrapadas a ras de suelo."},{"options":["PU toma todas las bolas fair/foul hasta la posición inicial de U1 o U3, y ULF y URF toman todas las demás decisiones","ULF y URF toman todas las decisiones de fair/foul","El árbitro de base más cercano toma todas las decisiones","PU no toma ninguna"],"q":"¿Cómo se reparte la responsabilidad de fair/foul en los Sistemas de Cinco y Seis Árbitros, según el Apéndice 5d?","why":"Al seguir una pelota cerca del poste de foul, el árbitro de outfield se mantiene bien atrás sobre la línea de foul para tener la profundidad adecuada y juzgar la trayectoria sobre el poste o la cerca."},{"options":["Siempre la toma el árbitro más lejano a la pelota","PU decide desde el plato","La decisión la toma el árbitro de base","Ambos corren hacia territorio fair en paralelo a la trayectoria de la pelota hasta tener un ángulo, y quien toma la decisión lo indica con una mano en el pecho o verbalmente"],"q":"En un fly al outfield en los Sistemas de Cinco y Seis Árbitros, ¿cómo deciden los árbitros de outfield quién toma la decisión?","why":"ULF y URF son responsables de todas las decisiones más allá del árbitro de base y detrás de los jugadores de cuadro: fair/foul, atrapada o no, y el estado de una pelota que sale del campo de juego."}],"title":"Apéndice 5c: Sistemas de cuatro, cinco y seis árbitros","nextLabel":"Has completado los ocho módulos obligatorios - consulta tu registro completo de evaluaciones"}};
